   213→// commitGeminiSession commits the session changes using the strategy.
   214→func commitGeminiSession(ctx *geminiSessionContext) error {
   215→	repoRoot, err := paths.RepoRoot()
   216→	if err != nil {
   217→		return fmt.Errorf("failed to get repo root: %w", err)
   218→	}
   219→
   220→	preState, err := LoadPrePromptState(ctx.sessionID)
   221→	if err != nil {
   222→		fmt.Fprintf(os.Stderr, "Warning: failed to load pre-prompt state: %v\n", err)
   223→	}
   224→	if preState != nil {
   225→		fmt.Fprintf(os.Stderr, "Loaded pre-prompt state: %d pre-existing untracked files, start message index: %d\n", len(preState.UntrackedFiles), preState.StartMessageIndex)
   226→	}
   227→
   228→	// Get transcript position from pre-prompt state
   229→	var startMessageIndex int
   230→	if preState != nil {
   231→		startMessageIndex = preState.StartMessageIndex
   232→	}
   233→
   234→	// Calculate token usage for this prompt/response cycle (Gemini-specific)
   235→	var tokenUsage *agent.TokenUsage
   236→	if ctx.transcriptPath != "" {
   237→		usage, tokenErr := geminicli.CalculateTokenUsageFromFile(ctx.transcriptPath, startMessageIndex)
   238→		if tokenErr != nil {
   239→			fmt.Fprintf(os.Stderr, "Warning: failed to calculate token usage: %v\n", tokenErr)
   240→		} else if usage != nil && usage.APICallCount > 0 {
   241→			tokenUsage = usage
   242→			fmt.Fprintf(os.Stderr, "Token usage for this checkpoint: input=%d, output=%d, cache_read=%d, api_calls=%d\n",
   243→				tokenUsage.InputTokens, tokenUsage.OutputTokens, tokenUsage.CacheReadTokens, tokenUsage.APICallCount)
   244→		}
   245→	}
   246→
   247→	newFiles, err := ComputeNewFiles(preState)
   248→	if err != nil {
   249→		fmt.Fprintf(os.Stderr, "Warning: failed to compute new files: %v\n", err)
   250→	}
   251→
   252→	deletedFiles, err := ComputeDeletedFiles()
   253→	if err != nil {
   254→		fmt.Fprintf(os.Stderr, "Warning: failed to compute deleted files: %v\n", err)
   255→	}
   256→
   257→	relModifiedFiles := FilterAndNormalizePaths(ctx.modifiedFiles, repoRoot)
   258→	relNewFiles := FilterAndNormalizePaths(newFiles, repoRoot)
   259→	relDeletedFiles := FilterAndNormalizePaths(deletedFiles, repoRoot)
   260→
   261→	totalChanges := len(relModifiedFiles) + len(relNewFiles) + len(relDeletedFiles)
   262→	if totalChanges == 0 {
   263→		fmt.Fprintf(os.Stderr, "No files were modified during this session\n")
   264→		fmt.Fprintf(os.Stderr, "Skipping commit\n")
   265→		if cleanupErr := CleanupPrePromptState(ctx.sessionID); cleanupErr != nil {
   266→			fmt.Fprintf(os.Stderr, "Warning: failed to cleanup pre-prompt state: %v\n", cleanupErr)
   267→		}
   268→		return nil
   269→	}
   270→
   271→	logFileChanges(relModifiedFiles, relNewFiles, relDeletedFiles)
   272→
   273→	contextFile := filepath.Join(ctx.sessionDirAbs, paths.ContextFileName)
   274→	if err := createContextFileForGemini(contextFile, ctx.commitMessage, ctx.sessionID, ctx.allPrompts, ctx.summary); err != nil {
   275→		return fmt.Errorf("failed to create context file: %w", err)
   276→	}
   277→	fmt.Fprintf(os.Stderr, "Created context file: %s\n", ctx.sessionDir+"/"+paths.ContextFileName)
   278→
   279→	author, err := GetGitAuthor()
   280→	if err != nil {
   281→		return fmt.Errorf("failed to get git author: %w", err)
   282→	}
   283→
   284→	strat := GetStrategy()
   285→	if err := strat.EnsureSetup(); err != nil {
   286→		fmt.Fprintf(os.Stderr, "Warning: failed to ensure strategy setup: %v\n", err)
   287→	}
   288→
   289→	// Get agent type from the hook agent (determined by which hook command is running)
   290→	// This is authoritative - if we're in "entire hooks gemini session-end", it's Gemini CLI
   291→	hookAgent, agentErr := GetCurrentHookAgent()
   292→	if agentErr != nil {
   293→		return fmt.Errorf("failed to get agent: %w", agentErr)
   294→	}
   295→	agentType := hookAgent.Type()
   296→
   297→	// Get transcript identifier at start from pre-prompt state
   298→	var transcriptIdentifierAtStart string
   299→	if preState != nil {
   300→		transcriptIdentifierAtStart = preState.LastTranscriptIdentifier
   301→	}
   302→
   303→	saveCtx := strategy.SaveContext{
   304→		SessionID:                   ctx.sessionID,
   305→		ModifiedFiles:               relModifiedFiles,
   306→		NewFiles:                    relNewFiles,
   307→		DeletedFiles:                relDeletedFiles,
   308→		MetadataDir:                 ctx.sessionDir,
   309→		MetadataDirAbs:              ctx.sessionDirAbs,
   310→		CommitMessage:               ctx.commitMessage,
   311→		TranscriptPath:              ctx.transcriptPath,
   312→		AuthorName:                  author.Name,
   313→		AuthorEmail:                 author.Email,
   314→		AgentType:                   agentType,
   315→		TranscriptLinesAtStart:      startMessageIndex,
   316→		TranscriptIdentifierAtStart: transcriptIdentifierAtStart,
   317→		TokenUsage:                  tokenUsage,
   318→	}
   319→
   320→	if err := strat.SaveChanges(saveCtx); err != nil {
   321→		return fmt.Errorf("failed to save session: %w", err)
   322→	}
   323→
   324→	if cleanupErr := CleanupPrePromptState(ctx.sessionID); cleanupErr != nil {
   325→		fmt.Fprintf(os.Stderr, "Warning: failed to cleanup pre-prompt state: %v\n", cleanupErr)
   326→	}
   327→
   328→	fmt.Fprintf(os.Stderr, "Session saved successfully\n")
   329→	return nil
   330→}
