   462→// handleGeminiBeforeAgent handles the BeforeAgent hook for Gemini CLI.
   463→// This is equivalent to Claude Code's UserPromptSubmit - it fires when the user submits a prompt.
   464→// We capture the initial state here so we can track what files were modified during the session.
   465→// It also checks for concurrent sessions and blocks if another session has uncommitted changes.
   466→func handleGeminiBeforeAgent() error {
   467→	// Always use the Gemini agent for Gemini hooks (don't use GetAgent() which may
   468→	// return Claude based on auto-detection in environments like VSCode)
   469→	ag, err := agent.Get("gemini")
   470→	if err != nil {
   471→		return fmt.Errorf("failed to get gemini agent: %w", err)
   472→	}
   473→
   474→	// Parse hook input - BeforeAgent provides user prompt info similar to UserPromptSubmit
   475→	input, err := ag.ParseHookInput(agent.HookUserPromptSubmit, os.Stdin)
   476→	if err != nil {
   477→		return fmt.Errorf("failed to parse hook input: %w", err)
   478→	}
   479→
   480→	logCtx := logging.WithAgent(logging.WithComponent(context.Background(), "hooks"), ag.Name())
   481→
   482→	// Log with prompt if available (Gemini provides the user's prompt in BeforeAgent)
   483→	logArgs := []any{
   484→		slog.String("hook", "before-agent"),
   485→		slog.String("hook_type", "agent"),
   486→		slog.String("model_session_id", input.SessionID),
   487→		slog.String("transcript_path", input.SessionRef),
   488→	}
   489→	if input.UserPrompt != "" {
   490→		// Truncate long prompts for logging
   491→		promptPreview := input.UserPrompt
   492→		if len(promptPreview) > 100 {
   493→			promptPreview = promptPreview[:100] + "..."
   494→		}
   495→		logArgs = append(logArgs, slog.String("prompt_preview", promptPreview))
   496→	}
   497→	logging.Info(logCtx, "gemini-before-agent", logArgs...)
   498→
   499→	if input.SessionID == "" {
   500→		return errors.New("no session_id in input")
   501→	}
   502→
   503→	// Capture pre-prompt state with transcript position (Gemini-specific)
   504→	// This captures both untracked files and the current transcript message count
   505→	// so we can calculate token usage for just this prompt/response cycle
   506→	if err := CaptureGeminiPrePromptState(input.SessionID, input.SessionRef); err != nil {
   507→		return fmt.Errorf("failed to capture pre-prompt state: %w", err)
   508→	}
   509→
   510→	// If strategy implements SessionInitializer, call it to initialize session state
   511→	strat := GetStrategy()
   512→	if initializer, ok := strat.(strategy.SessionInitializer); ok {
   513→		agentType := ag.Type()
   514→		if err := initializer.InitializeSession(input.SessionID, agentType, input.SessionRef); err != nil {
   515→			fmt.Fprintf(os.Stderr, "Warning: failed to initialize session state: %v\n", err)
   516→		}
   517→	}
   518→
   519→	return nil
   520→}
