   522→// handleGeminiAfterAgent handles the AfterAgent hook for Gemini CLI.
   523→// This fires after the agent has finished processing and generated a response.
   524→// This is equivalent to Claude Code's "Stop" hook - it commits the session changes with metadata.
   525→// AfterAgent fires after EVERY user prompt/response cycle, making it the correct place
   526→// for checkpoint creation (not SessionEnd, which only fires on explicit exit).
   527→func handleGeminiAfterAgent() error {
   528→	// Skip on default branch for strategies that don't allow it
   529→	if skip, branchName := ShouldSkipOnDefaultBranchForStrategy(); skip {
   530→		fmt.Fprintf(os.Stderr, "Entire: skipping on branch '%s' - create a feature branch to use Entire tracking\n", branchName)
   531→		return nil
   532→	}
   533→
   534→	// Always use Gemini agent for Gemini hooks
   535→	ag, err := agent.Get("gemini")
   536→	if err != nil {
   537→		return fmt.Errorf("failed to get gemini agent: %w", err)
   538→	}
   539→
   540→	// Parse hook input using HookStop - AfterAgent provides the same data as Stop
   541→	// (session_id, transcript_path) which is what we need for committing
   542→	input, err := ag.ParseHookInput(agent.HookStop, os.Stdin)
   543→	if err != nil {
   544→		return fmt.Errorf("failed to parse hook input: %w", err)
   545→	}
   546→
   547→	logCtx := logging.WithAgent(logging.WithComponent(context.Background(), "hooks"), ag.Name())
   548→	logging.Info(logCtx, "gemini-after-agent",
   549→		slog.String("hook", "after-agent"),
   550→		slog.String("hook_type", "agent"),
   551→		slog.String("model_session_id", input.SessionID),
   552→		slog.String("transcript_path", input.SessionRef),
   553→	)
   554→
   555→	sessionID := input.SessionID
   556→	if sessionID == "" {
   557→		sessionID = unknownSessionID
   558→	}
   559→
   560→	transcriptPath := input.SessionRef
   561→	if transcriptPath == "" || !fileExists(transcriptPath) {
   562→		return fmt.Errorf("transcript file not found or empty: %s", transcriptPath)
   563→	}
   564→
   565→	// Create session context and commit
   566→	ctx := &geminiSessionContext{
   567→		sessionID:      sessionID,
   568→		transcriptPath: transcriptPath,
   569→	}
   570→
   571→	if err := setupGeminiSessionDir(ctx); err != nil {
   572→		return err
   573→	}
   574→
   575→	if err := extractGeminiMetadata(ctx); err != nil {
   576→		return err
   577→	}
   578→
   579→	return commitGeminiSession(ctx)
   580→}
